<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric,OptimizationRun};
use Illuminate\Foundation\Testing\DatabaseTransactions;
final class EntityModelSelectionEvidenceTest extends TestCase{
 use DatabaseTransactions;
 public function test_candidate_scores_decompose_and_are_archived_with_rejected_alternatives():void{
  $u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'fixture','currency'=>'USD']);for($i=30;$i>=1;$i--){$x=20+(30-$i)*8;PerformanceMetric::create(['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1','metric_definition'=>['version'=>'meta-pixel-purchase-1','normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1','conversion'=>'offsite_conversion.fb_pixel_purchase','value'=>'offsite_conversion.fb_pixel_purchase']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','currency'=>'USD','date'=>now()->subDays($i)->toDateString(),'spend'=>$x,'impressions'=>1000,'clicks'=>100,'conversions'=>10,'conversion_value'=>1000*(-expm1(-.01*$x))]);}$r=$this->actingAs($u,'sanctum')->postJson('/api/v1/analytics/entity-optimization',['entity_level'=>'campaign','objective'=>'MAXIMIZE_REVENUE','budget'=>3000,'provider'=>'meta'])->assertOk()->assertJsonPath('data.status','ok');$source=$r->json('data.allocations.0.source');$this->assertCount(4,$source['candidates']);$valid=[];foreach($source['candidates']as$v){if($v['score']!==null)$this->assertEqualsWithDelta($v['validation_rmse_rel']+$v['complexity_penalty']+$v['instability_penalty'],$v['score'],2e-6);if($v['status']==='valid')$valid[]=$v;}$pred=$source['validation']['holdout_predictions'];$this->assertCount(9,$pred);$this->assertSame(22,$pred[0]['positive_spend_observation_index']);$residualSquares=0;$sumObserved=0;foreach($pred as$p){$this->assertEqualsWithDelta($p['observed_response']-$p['predicted_response'],$p['residual'],1e-10);$residualSquares+=$p['residual']**2;$sumObserved+=$p['observed_response'];}$this->assertEqualsWithDelta(sqrt($residualSquares/count($pred))/($sumObserved/count($pred)),$source['validation']['validation_rmse_rel'],1e-6);$scores=array_column($valid,'score');$this->assertEquals(min($scores),$source['validation']['score']);$this->assertSame($source,OptimizationRun::findOrFail($r->json('data.run_id'))->result['allocations'][0]['source']);
 }
}
